def __init__(
    self,
    name: str | None = None,
    commands: cabc.MutableMapping[str, Command]
    | cabc.Sequence[Command]
    | None = None,
    invoke_without_command: bool = False,
    no_args_is_help: bool | None = None,
    subcommand_metavar: str | None = None,
    chain: bool = False,
    result_callback: t.Callable[..., t.Any] | None = None,
    **kwargs: t.Any,
) -> None:
    super().__init__(name, **kwargs)

    if commands is None:
        commands = {}
    elif isinstance(commands, abc.Sequence):
        commands = {c.name: c for c in commands if c.name is not None}

    #: The registered subcommands by their exported names.
    self.commands: cabc.MutableMapping[str, Command] = commands

    if no_args_is_help is None:
        no_args_is_help = not invoke_without_command

    self.no_args_is_help = no_args_is_help
    self.invoke_without_command = invoke_without_command

    if subcommand_metavar is None:
        if chain:
            subcommand_metavar = "COMMAND1 [ARGS]... [COMMAND2 [ARGS]...]..."
        else:
            subcommand_metavar = "COMMAND [ARGS]..."

    self.subcommand_metavar = subcommand_metavar
    self.chain = chain
    # The result callback that is stored. This can be set or
    # overridden with the :func:`result_callback` decorator.
    self._result_callback = result_callback

    if self.chain:
        for param in self.params:
            if isinstance(param, Argument) and not param.required:
                raise RuntimeError(
                    "A group in chain mode cannot have optional arguments."
                )

def _has_binary_buffer(
    stream: t.BinaryIO | t.TextIO,
) -> t.TypeGuard[_BufferedTextPagerStream]:
    # TextIO is wider than TextIOWrapper; text-only streams such as StringIO
    # are valid TextIO values but do not expose a binary buffer to wrap.
    return getattr(stream, "buffer", None) is not None

def _interpret_color(color: int | tuple[int, int, int] | str, offset: int = 0) -> str:
    if isinstance(color, int):
        return f"{38 + offset};5;{color:d}"

    if isinstance(color, (tuple, list)):
        r, g, b = color
        return f"{38 + offset};2;{r:d};{g:d};{b:d}"

    return str(_ansi_colors[color] + offset)

def unsign(self, signed_value: _t_str_bytes) -> bytes:
    """Unsigns the given string."""
    signed_value = want_bytes(signed_value)

    if self.sep not in signed_value:
        raise BadSignature(f"No {self.sep!r} found in value")

    value, sig = signed_value.rsplit(self.sep, 1)

    if self.verify_signature(value, sig):
        return value

    raise BadSignature(f"Signature {sig!r} does not match", payload=value)

def dumps(self, obj: _t.Any, salt: _t_opt_str_bytes = None) -> _t_str_bytes:
    """Returns a signed string serialized with the internal
    serializer. The return value can be either a byte or unicode
    string depending on the format of the internal serializer.
    """
    payload = want_bytes(self.dump_payload(obj))
    rv = self.make_signer(salt).sign(payload)

    if self.is_text_serializer:
        return rv.decode("utf-8")

    return rv

def make_signer(self, salt: _t_opt_str_bytes = None) -> Signer:
    """Creates a new instance of the signer to be used. The default
    implementation uses the :class:`.Signer` base class.
    """
    if salt is None:
        salt = self.salt

    return self.signer(self.secret_keys, salt=salt, **self.signer_kwargs)

def validate(self, signed_value, max_age=None):
    """Only validates the given signed value. Returns ``True`` if
    the signature exists and is valid."""
    try:
        self.unsign(signed_value, max_age=max_age)
        return True
    except BadSignature:
        return False

def loads_unsafe(self, s, max_age=None, salt=None):
    load_kwargs = {"max_age": max_age}
    load_payload_kwargs = {}
    return self._loads_unsafe_impl(s, salt, load_kwargs, load_payload_kwargs)

def validate(self, signed_value: _t_str_bytes, max_age: _t_opt_int = None) -> bool:
    """Only validates the given signed value. Returns ``True`` if
    the signature exists and is valid."""
    try:
        self.unsign(signed_value, max_age=max_age)
        return True
    except BadSignature:
        return False

def iter_params_for_processing(
    invocation_order: t.Sequence["Parameter"],
    declaration_order: t.Sequence["Parameter"],
) -> t.List["Parameter"]:
    """Given a sequence of parameters in the order as should be considered
    for processing and an iterable of parameters that exist, this returns
    a list in the correct order as they should be processed.
    """

    def sort_key(item: "Parameter") -> t.Tuple[bool, float]:
        try:
            idx: float = invocation_order.index(item)
        except ValueError:
            idx = float("inf")

        return not item.is_eager, idx

    return sorted(declaration_order, key=sort_key)

@property
def output(self) -> str:
    """The (standard) output as unicode string."""
    return self.stdout

def get_default(
    self, ctx: Context, call: bool = True
) -> t.Optional[t.Union[t.Any, t.Callable[[], t.Any]]]:
    # If we're a non boolean flag our default is more complex because
    # we need to look at all flags in the same group to figure out
    # if we're the default one in which case we return the flag
    # value as default.
    if self.is_flag and not self.is_bool_flag:
        for param in ctx.command.params:
            if param.name == self.name and param.default:
                return t.cast(Option, param).flag_value

        return None

    return super().get_default(ctx, call=call)

def get_help(self) -> str:
    """Helper method to get formatted help page for the current
    context and command.
    """
    return self.command.get_help(self)

def __exit__(
    self,
    exc_type: type[BaseException] | None,
    exc_value: BaseException | None,
    tb: TracebackType | None,
) -> None:
    self._depth -= 1
    if self._depth == 0:
        self.close()
    pop_context()

