def _parse_decls(
    self, decls: cabc.Sequence[str], expose_value: bool
) -> tuple[str | None, list[str], list[str]]:
    if not decls:
        if not expose_value:
            return None, [], []
        raise TypeError("Argument is marked as exposed, but does not have a name.")
    if len(decls) == 1:
        name = arg = decls[0]
        name = name.replace("-", "_").lower()
    else:
        raise TypeError(
            "Arguments take exactly one parameter declaration, got"
            f" {len(decls)}: {decls}."
        )
    return name, [arg], []

@curry
def memoize(func, cache=None, key=None):
    """ Cache a function's result for speedy future evaluation

    Considerations:
        Trades memory for speed.
        Only use on pure functions.

    >>> def add(x, y):  return x + y
    >>> add = memoize(add)

    Or use as a decorator

    >>> @memoize
    ... def add(x, y):
    ...     return x + y

    Use the ``cache`` keyword to provide a dict-like object as an initial cache

    >>> @memoize(cache={(1, 2): 3})
    ... def add(x, y):
    ...     return x + y

    Note that the above works as a decorator because ``memoize`` is curried.

    It is also possible to provide a ``key(args, kwargs)`` function that
    calculates keys used for the cache, which receives an ``args`` tuple and
    ``kwargs`` dict as input, and must return a hashable value.  However,
    the default key function should be sufficient most of the time.

    >>> # Use key function that ignores extraneous keyword arguments
    >>> @memoize(key=lambda args, kwargs: args)
    ... def add(x, y, verbose=False):
    ...     if verbose:
    ...         print('Calculating %s + %s' % (x, y))
    ...     return x + y
    """
    if cache is None:
        cache = {}

    try:
        may_have_kwargs = has_keywords(func) is not False
        # Is unary function (single arg, no variadic argument or keywords)?
        is_unary = is_arity(1, func)
    except TypeError:  # pragma: no cover
        may_have_kwargs = True
        is_unary = False

    if key is None:
        if is_unary:
            def key(args, kwargs):
                return args[0]
        elif may_have_kwargs:
            def key(args, kwargs):
                return (
                    args or None,
                    frozenset(kwargs.items()) if kwargs else None,
                )
        else:
            def key(args, kwargs):
                return args

    def memof(*args, **kwargs):
        k = key(args, kwargs)
        try:
            return cache[k]
        except TypeError:
            raise TypeError("Arguments to memoized function must be hashable")
        except KeyError:
            cache[k] = result = func(*args, **kwargs)
            return result

    try:
        memof.__name__ = func.__name__
    except AttributeError:
        pass
    memof.__doc__ = func.__doc__
    memof.__wrapped__ = func
    return memof

def __init__(self, *funcs):
    if len(funcs) == 1 and not callable(funcs[0]):
        funcs = funcs[0]
    self.funcs = tuple(funcs)

@instanceproperty(classval=__doc__)
def __doc__(self):
    exc = self.exc
    try:
        if isinstance(exc, tuple):
            exc_name = '(%s)' % ', '.join(
                map(attrgetter('__name__'), exc),
            )
        else:
            exc_name = exc.__name__

        return dedent(
            """\
            A wrapper around {inst.func.__name__!r} that will except:
            {exc}
            and handle any exceptions with {inst.handler.__name__!r}.

            Docs for {inst.func.__name__!r}:
            {inst.func.__doc__}

            Docs for {inst.handler.__name__!r}:
            {inst.handler.__doc__}
            """
        ).format(
            inst=self,
            exc=exc_name,
        )
    except AttributeError:
        return type(self).__doc__

def diff(*seqs, **kwargs):
    """ Return those items that differ between sequences

    >>> list(diff([1, 2, 3], [1, 2, 10, 100]))
    [(3, 10)]

    Shorter sequences may be padded with a ``default`` value:

    >>> list(diff([1, 2, 3], [1, 2, 10, 100], default=None))
    [(3, 10), (None, 100)]

    A ``key`` function may also be applied to each item to use during
    comparisons:

    >>> list(diff(['apples', 'bananas'], ['Apples', 'Oranges'], key=str.lower))
    [('bananas', 'Oranges')]
    """
    N = len(seqs)
    if N == 1 and isinstance(seqs[0], list):
        seqs = seqs[0]
        N = len(seqs)
    if N < 2:
        raise TypeError('Too few sequences given (min 2 required)')
    default = kwargs.get('default', no_default)
    if default == no_default:
        iters = zip(*seqs)
    else:
        iters = itertools.zip_longest(*seqs, fillvalue=default)
    key = kwargs.get('key', None)
    if key is None:
        for items in iters:
            if items.count(items[0]) != N:
                yield items
    else:
        for items in iters:
            vals = tuple(map(key, items))
            if vals.count(vals[0]) != N:
                yield items

def getter(index):
    if isinstance(index, list):
        if len(index) == 1:
            index = index[0]
            return lambda x: (x[index],)
        else:
            return operator.itemgetter(*index)
    else:
        return operator.itemgetter(index)

def __init__(self, func, *args, **kwargs):
    if not callable(func):
        raise TypeError("Input must be callable")

    # curry- or functools.partial-like object?  Unpack and merge arguments
    if (hasattr(func, 'func')
            and hasattr(func, 'args')
            and hasattr(func, 'keywords')
            and isinstance(func.args, tuple)):
        _kwargs = {}
        if func.keywords:
            _kwargs.update(func.keywords)
        _kwargs.update(kwargs)
        kwargs = _kwargs
        args = func.args + args
        func = func.func

    if kwargs:
        self._partial = partial(func, *args, **kwargs)
    else:
        self._partial = partial(func, *args)

    self.__doc__ = getattr(func, '__doc__', None)
    self.__name__ = getattr(func, '__name__', '<curry>')

def __getslice__(self, start, stop):
    iter_slice = self.iter_slice(start, stop, 1)
    return self.from_iterable(iter_slice)

def _parse_wraps_expected(expected):
    # expected takes a pretty powerful argument, it's processed
    # here. admittedly this would be less trouble if I relied on
    # OrderedDict (there's an impl of that in the commit history if
    # you look
    if expected is None:
        expected = []
    elif isinstance(expected, basestring):
        expected = [(expected, NO_DEFAULT)]

    expected_items = []
    try:
        expected_iter = iter(expected)
    except TypeError as e:
        raise ValueError('"expected" takes string name, sequence of string names,'
                         ' iterable of (name, default) pairs, or a mapping of '
                         ' {name: default}, not %r (got: %r)' % (expected, e))
    for argname in expected_iter:
        if isinstance(argname, basestring):
            # dict keys and bare strings
            try:
                default = expected[argname]
            except TypeError:
                default = NO_DEFAULT
        else:
            # pairs
            try:
                argname, default = argname
            except (TypeError, ValueError):
                raise ValueError('"expected" takes string name, sequence of string names,'
                                 ' iterable of (name, default) pairs, or a mapping of '
                                 ' {name: default}, not %r')
        if not isinstance(argname, basestring):
            raise ValueError('all "expected" argnames must be strings, not %r' % (argname,))

        expected_items.append((argname, default))

    return expected_items

def windowed_iter(src, size):
    """Returns tuples with length *size* which represent a sliding
    window over iterable *src*.

    >>> list(windowed_iter(range(7), 3))
    [(0, 1, 2), (1, 2, 3), (2, 3, 4), (3, 4, 5), (4, 5, 6)]

    If the iterable is too short to make a window of length *size*,
    then no window tuples are returned.

    >>> list(windowed_iter(range(3), 5))
    []
    """
    # TODO: lists? (for consistency)
    tees = itertools.tee(src, size)
    try:
        for i, t in enumerate(tees):
            for _ in xrange(i):
                next(t)
    except StopIteration:
        return izip([])
    return izip(*tees)

def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    for item in iterable:
        if isinstance(item, Iterable) and not isinstance(item, basestring):
            for subitem in flatten_iter(item):
                yield subitem
        else:
            yield item

def poplast(self, k=_MISSING, default=_MISSING):
    """Remove and return the most-recently inserted value under the key
    *k*, or the most-recently inserted key if *k* is not
    provided. If no values remain under *k*, it will be removed
    from the OMD.  Raises :exc:`KeyError` if *k* is not present in
    the dictionary, or the dictionary is empty.
    """
    if k is _MISSING:
        if self:
            k = self.root[PREV][KEY]
        else:
            raise KeyError('empty %r' % type(self))
    try:
        self._remove(k)
    except KeyError:
        if default is _MISSING:
            raise KeyError(k)
        return default
    values = super(OrderedMultiDict, self).__getitem__(k)
    v = values.pop()
    if not values:
        super(OrderedMultiDict, self).__delitem__(k)
    return v

def pop(self, k, default=_MISSING):
    """Remove all values under key *k*, returning the most-recently
    inserted value. Raises :exc:`KeyError` if the key is not
    present and no *default* is provided.
    """
    try:
        return self.popall(k)[-1]
    except KeyError:
        if default is _MISSING:
            raise KeyError(k)
    return default

def __repr__(self):
    if self._step == 1:
        return f"numeric_range({self._start!r}, {self._stop!r})"
    return (
        f"numeric_range({self._start!r}, {self._stop!r}, {self._step!r})"
    )

def peek(self, default=_marker):
    try:
        peeked = next(self)
    except StopIteration:
        if default is _marker:
            raise
        return default
    if self._index is None:
        self._index = len(self._cache)
    self._index -= 1
    return peeked

def __bool__(self):
    try:
        self.peek()
    except StopIteration:
        return False
    return True

def __reversed__(self):
    return iter(
        numeric_range(
            self._get_by_index(-1), self._start - self._step, -self._step
        )
    )

def last(iterable, default=_marker):
    """Return the last item of *iterable*, or *default* if *iterable* is
    empty.

        >>> last([0, 1, 2, 3])
        3
        >>> last([], 'some default')
        'some default'

    If *default* is not provided and there are no items in the iterable,
    raise ``ValueError``.
    """
    try:
        if isinstance(iterable, Sequence):
            return iterable[-1]
        # Work around https://bugs.python.org/issue38525
        if getattr(iterable, '__reversed__', None):
            return next(reversed(iterable))
        return deque(iterable, maxlen=1)[-1]
    except (IndexError, TypeError, StopIteration):
        if default is _marker:
            raise ValueError(
                'last() was called on an empty iterable, '
                'and no default value was provided.'
            )
        return default

def always_reversible(iterable):
    """An extension of :func:`reversed` that supports all iterables, not
    just those which implement the ``Reversible`` or ``Sequence`` protocols.

        >>> print(*always_reversible(x for x in range(3)))
        2 1 0

    If the iterable is already reversible, this function returns the
    result of :func:`reversed()`. If the iterable is not reversible,
    this function will cache the remaining items in the iterable and
    yield them in reverse order, which may require significant storage.
    """
    try:
        return reversed(iterable)
    except TypeError:
        return reversed(list(iterable))

def __init__(self, *args):
    argc = len(args)
    if argc == 1:
        (self._stop,) = args
        self._start = type(self._stop)(0)
        self._step = type(self._stop - self._start)(1)
    elif argc == 2:
        self._start, self._stop = args
        self._step = type(self._stop - self._start)(1)
    elif argc == 3:
        self._start, self._stop, self._step = args
    elif argc == 0:
        raise TypeError(
            f'numeric_range expected at least 1 argument, got {argc}'
        )
    else:
        raise TypeError(
            f'numeric_range expected at most 3 arguments, got {argc}'
        )

    self._zero = type(self._step)(0)
    if self._step == self._zero:
        raise ValueError('numeric_range() arg 3 must not be zero')
    self._growing = self._step > self._zero

def __getitem__(self, key):
    if isinstance(key, int):
        return self._get_by_index(key)
    elif isinstance(key, slice):
        step = self._step if key.step is None else key.step * self._step

        if key.start is None or key.start <= -self._len:
            start = self._start
        elif key.start >= self._len:
            start = self._stop
        else:  # -self._len < key.start < self._len
            start = self._get_by_index(key.start)

        if key.stop is None or key.stop >= self._len:
            stop = self._stop
        elif key.stop <= -self._len:
            stop = self._start
        else:  # -self._len < key.stop < self._len
            stop = self._get_by_index(key.stop)

        return numeric_range(start, stop, step)
    else:
        raise TypeError(
            'numeric range indices must be '
            f'integers or slices, not {type(key).__name__}'
        )

def __eq__(self, other):
    if isinstance(other, numeric_range):
        empty_self = not bool(self)
        empty_other = not bool(other)
        if empty_self or empty_other:
            return empty_self and empty_other  # True if both empty
        else:
            return (
                self._start == other._start
                and self._step == other._step
                and self._get_by_index(-1) == other._get_by_index(-1)
            )
    else:
        return False

